describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 2000, costCents: 700 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(calc.computeShippingCents([noWeightLine("a")], 100)).toBe(0);
    });

    it("selects first bracket for weight within range", () => {
      // 200g → bracket 0-500g = 300 cents
      expect(calc.computeShippingCents([line("a", 200)], 100)).toBe(300);
    });

    it("selects bracket at upper boundary", () => {
      // exactly 500g → bracket ≤500g = 300
      expect(calc.computeShippingCents([line("a", 500)], 100)).toBe(300);
    });

    it("selects next bracket just above boundary", () => {
      // 501g → bracket ≤2000g = 700
      expect(calc.computeShippingCents([line("a", 501)], 100)).toBe(700);
    });

    it("selects heaviest bracket at its boundary", () => {
      expect(calc.computeShippingCents([line("a", 5000)], 100)).toBe(1200);
    });

    it("uses heaviest bracket cost as default overflow", () => {
      // 6000g > all brackets, no overflowCostCents → last bracket cost
      expect(calc.computeShippingCents([line("a", 6000)], 100)).toBe(1200);
    });

    it("uses explicit overflowCostCents when set", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        brackets,
        2000,
      );
      expect(
        calcWithOverflow.computeShippingCents([line("a", 6000)], 100),
      ).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      // 2 × 300g = 600g → bracket ≤2000g = 700
      const lines = [line("a", 300, 2)];
      expect(calc.computeShippingCents(lines, 100)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered: WeightBracket[] = [
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc2 = new WeightBasedShippingCalculator(unordered);
      // 400g → should match ≤500g = 300
      expect(calc2.computeShippingCents([line("a", 400)], 100)).toBe(300);
    });
  });
});

