    expect(() => cart.updateQuantity("missing", 5)).toThrow(
      "not in the cart",
    );
  });

  it("clear empties the cart", () => {
    cart.add(mkProduct("a", 500), 2);
    cart.add(mkProduct("b", 300), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot is a deep copy (mutations do not affect cart)", () => {
    cart.add(mkProduct("a", 500), 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 1;
    expect(cart.snapshot()[0].quantity).toBe(2);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(500);
  });
});

describe("Cart — totals with mocked seams", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("computes subtotal from line prices × quantities", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2); // 2000
    cart.add(mkProduct("b", 500), 3); // 1500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500);
  });

  it("applies discount then computes tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(250),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(mkProduct("a", 2000), 1);
    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // tax should be called with discounted subtotal (2000 - 500 = 1500)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US");
    expect(totals.taxCents).toBe(250);
    // total = discountedSubtotal + tax + shipping = 1500 + 250 + 0
    expect(totals.totalCents).toBe(1750);
  });

  it("clamps discount to [0, subtotal]", () => {
    // discount returns more than subtotal → clamped
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("shipping is computed on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();

    // shipping sees discounted subtotal = 1000 - 200 = 800
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses custom region for tax", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("full pipeline: subtotal → discount → tax → shipping → total", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(70),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(mkProduct("a", 1000), 1);
    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(300);
    expect(totals.taxCents).toBe(70);
    expect(totals.shippingCents).toBe(500);
    // total = (1000 - 300) + 70 + 500 = 1270
    expect(totals.totalCents).toBe(1270);
  });
});

describe("Cart — async checkout()", () => {
  it("returns totals and lines for basic checkout", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const result = await cart.checkout();

    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });

    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(3000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available: true but quantity insufficient)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("passes checkout when inventory is sufficient", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes checkout when available is true and no availableQuantity", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy,
      shippingCalculator,
      region: "US-CA",
    });
    cart.add(mkProduct("a", 2000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ asyncTaxProvider });

    // subtotal=2000, discount=200, discountedSubtotal=1800
    // tax = 10% of 1800 = 180
    // shipping = 300
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(180);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(2280);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "fetch failed",
    );
  });

  it("full checkout: price refresh + inventory + async tax + discount + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "DE" });
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 500), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1200) // a → 1200
        .mockResolvedValueOnce(600), // b → 600
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.19), // 19% German VAT
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal = 1200*2 + 600*1 = 3000
    // discount = 100 (mocked)
    // discountedSubtotal = 2900
    // tax = floor(2900 * 0.19) = floor(551) = 551
    // shipping = 500
    // total = 2900 + 551 + 500 = 3951
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(551);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(3951);

    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("DE");
  });
});
"}

